import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_equals_TriageGen0Test {

    private Element element1;
    private Element element2;
    private Object nonElementObject;

    @Before
    public void setUp() {
        Tag tag = Tag.valueOf("div");
        element1 = new Element(tag, "http://example.com", null);
        element2 = new Element(tag, "http://example.com", null);
        nonElementObject = new Object();
    }

    @Test
    public void testEqualsSameObject() {
        assertTrue(element1.equals(element1));
    }

    @Test
    public void testEqualsDifferentObjects() {
        assertFalse(element1.equals(element2));
    }

    @Test
    public void testEqualsNull() {
        assertFalse(element1.equals(null));
    }

    @Test
    public void testEqualsDifferentClass() {
        assertFalse(element1.equals(nonElementObject));
    }

    @Test
    public void testEqualsSuperclassEquality() {
        // Assuming super.equals(o) returns true for equality in superclass
        // Mock or simulate superclass behavior if necessary
        // For this test, we assume that super.equals(o) is true
        assertTrue(element1.equals(element2));
    }

    @Test
    public void testEqualsSuperclassInequality() {
        // Assuming super.equals(o) returns false for inequality in superclass
        // Mock or simulate superclass behavior if necessary
        // For this test, we assume that super.equals(o) is false
        assertFalse(element1.equals(nonElementObject));
    }

    @Test
    public void testEqualsObjectCasting() {
        assertTrue(element1.equals((Object) element1));
    }
}
